import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String lineA = br.readLine();
        if (lineA == null) return;
        int a = Integer.parseInt(lineA.trim());

        String lineN = br.readLine();
        if (lineN == null) return;
        int n = Integer.parseInt(lineN.trim());

        int moedasPorMarinheiro = a / (n + 2);
        int moedasCapitao = 2 * moedasPorMarinheiro;

        System.out.println(moedasCapitao);
    }
}
